#!/usr/bin/env node
// Compact timeline of a conversation JSONL: timestamps, roles, tool calls, errors, user text.
import { createInterface } from 'node:readline';

const rl = createInterface({ input: process.stdin });
const t0 = { v: null };
function hhmmss(ts) {
  if (!ts) return '  ?  ';
  const d = new Date(ts);
  return d.toISOString().slice(11, 19);
}
function clip(s, n) {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}
let prevTs = null;
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.time || null;
  let gap = '';
  if (ts && prevTs) {
    const d = (new Date(ts) - new Date(prevTs)) / 1000;
    if (d >= 20) gap = `  <<< +${d.toFixed(0)}s`;
  }
  if (ts) prevTs = ts;
  const m = e.message;
  if (!m) {
    if (e.attachment) continue;
    continue;
  }
  const role = m.role;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  for (const c of content) {
    if (c.type === 'text' && c.text && c.text.trim()) {
      console.log(`${hhmmss(ts)} ${role === 'user' ? 'USER' : 'asst'}: ${clip(c.text, role === 'user' ? 900 : 400)}${gap}`);
    } else if (c.type === 'thinking') {
      // skip thinking by default
    } else if (c.type === 'tool_use') {
      const inp = c.input || {};
      const desc = inp.command || inp.file_path || inp.pattern || inp.prompt || inp.query || inp.url || JSON.stringify(inp).slice(0, 200);
      console.log(`${hhmmss(ts)}   TOOL ${c.name}: ${clip(desc, 220)}${gap}`);
    } else if (c.type === 'tool_result') {
      const isErr = c.is_error;
      let txt = c.content;
      if (Array.isArray(txt)) txt = txt.map((x) => x.text || '').join(' ');
      if (isErr || /error|not found|failed|denied|refus/i.test(String(txt).slice(0, 300))) {
        console.log(`${hhmmss(ts)}     ${isErr ? 'ERR ' : 'res?'} ${clip(txt, 300)}${gap}`);
      } else if (gap) {
        console.log(`${hhmmss(ts)}     res  ${clip(txt, 90)}${gap}`);
      }
    }
  }
}

